    return `<section class="engineering-commercial"><div class="engineering-section-head"><div><small>BOM · QUOTE · PDF · PHASE 7</small><h2>材料表與報價</h2></div><span>人工價格 · TWD</span></div>${commercial.error?`<p class="engineering-form-error" role="alert">${esc(commercial.error)}</p>`:""}${commercial.notice?`<p class="engineering-notice" role="status">${esc(commercial.notice)}</p>`:""}<details open><summary>從保存的 Design Snapshot 產生 BOM</summary>${designActions}</details><details open><summary>BOM Snapshots <span>${boms.length}</span></summary><div class="engineering-bom-list">${bomCards}</div></details><details open><summary>Quote Draft／Published <span>${quotes.length}</span></summary><div class="engineering-quote-list">${quoteCards}</div></details></section>`;
